contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint addAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (addAmount)); require(addAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= addAmount);

        uint beforeC = address(c).balance;
        uint beforeCaller = address(this).balance;

        c.addToBalance{value: addAmount}(); if (__ESBMC_reverted()) return;

        uint recorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        uint afterAddC = address(c).balance;
        uint afterAddCaller = address(this).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterWithdrawC = address(c).balance;
        uint afterWithdrawCaller = address(this).balance;

        assert(
            !reverted &&
            c.getBalance(address(this)) == 0 &&
            afterWithdrawCaller == afterAddCaller + recorded &&
            afterWithdrawC == afterAddC - recorded &&
            afterAddCaller == beforeCaller - addAmount &&
            afterAddC == beforeC + addAmount
        );
    }

    receive() external payable {}
}

