        c = new Reentrance();
    }

    function _run(uint256 addAmount) internal {
        addAmount = bound(addAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= addAmount);
        uint beforeC = address(c).balance;
        uint beforeCaller = address(this).balance;
        try c.addToBalance{value: addAmount}() {} catch { return; }
        uint256 recorded;
        try c.getBalance(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        uint afterAddC = address(c).balance;
        uint afterAddCaller = address(this).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterWithdrawC = address(c).balance;
        uint afterWithdrawCaller = address(this).balance;
        assertTrue(!reverted &&
            c.getBalance(address(this)) == 0 &&
            afterWithdrawCaller == afterAddCaller + recorded &&
            afterWithdrawC == afterAddC - recorded &&
            afterAddCaller == beforeCaller - addAmount &&
